    capacity = get(instance, "capacity", None)
    if capacity is None: capacity = get(instance, "vehicle_capacity", None)
    if capacity is None: capacity = get(instance, "vehicleCapacity", None)
    if capacity is None:
        capacity = sum(demands[c] if isinstance(c, int) and 0 <= c < len(demands) else 1 for c in customers)
    if not capacity:
        capacity = sum(demands[c] if isinstance(c, int) and 0 <= c < len(demands) else 1 for c in customers)

    def coord_of(n):
        if 0 <= n < len(coords):
            p = coords[n]
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                return p[0], p[1]
        return 0.0, 0.0

    def demand_of(c):
        return demands[c] if isinstance(c, int) and 0 <= c < len(demands) else 1

    def dist(a, b):
        ax, ay = coord_of(a)
        bx, by = coord_of(b)
        dx = ax - bx
        dy = ay - by
        return (dx * dx + dy * dy) ** 0.5

    depot = 0
    if isinstance(get(instance, "depot", None), int):
        depot = get(instance, "depot", None)

    rem = customers[:]
    rem.sort(key=lambda c: (dist(depot, c), c))
    routes = []

    while rem:
        route = []
        load = 0
        last = depot
        best_i = 0
        best_k = None
        for i, c in enumerate(rem):
            d = demand_of(c)
            if load + d <= capacity:
                k = (dist(depot, c), d, c)
                if best_k is None or k < best_k:
                    best_k = k
                    best_i = i
        c = rem.pop(best_i)
        route.append(c)
        load += demand_of(c)
        last = c
        while True:
            best_i = -1
            best_k = None
            for i, x in enumerate(rem):
                d = demand_of(x)
                if load + d > capacity:
                    continue
                k = (dist(last, x), dist(depot, x), d, x)
                if best_k is None or k < best_k:
                    best_k = k
                    best_i = i
            if best_i < 0:
                break
            c = rem.pop(best_i)
            route.append(c)
            load += demand_of(c)
            last = c
        routes.append(route)

    def route_cost(r):
        if not r:
            return 0.0
        s = dist(depot, r[0])
        for i in range(len(r) - 1):
            s += dist(r[i], r[i + 1])
        return s + dist(r[-1], depot)

    changed = True
    while changed:
        changed = False
        for ri in range(len(routes)):
            r = routes[ri]
            if len(r) < 4:
                continue
            for i in range(len(r) - 2):
                a = depot if i == 0 else r[i - 1]
                b = r[i]
                for j in range(i + 1, len(r)):
                    c = r[j]
                    d = depot if j == len(r) - 1 else r[j + 1]
                    if dist(a, b) + dist(c, d) > dist(a, c) + dist(b, d) + 1e-12:
                        routes[ri] = r[:i] + r[i:j + 1][::-1] + r[j + 1:]
                        changed = True
                        break
                if changed:
                    break
            if changed:
                break

    changed = True
    while changed:
        changed = False
        loads = [sum(demand_of(x) for x in r) for r in routes]
        for i in range(len(routes)):
            if changed:
                break
            ra = routes[i]
            for p, c in enumerate(ra):
                dc = demand_of(c)
                prev = depot if p == 0 else ra[p - 1]
                nxt = depot if p == len(ra) - 1 else ra[p + 1]
                rem_gain = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                for j in range(len(routes)):
                    if i == j or loads[j] + dc > capacity:
                        continue
                    rb = routes[j]
                    best_pos = 0
                    best_ins = dist(depot, c) + dist(c, depot)
                    prevb = depot
                    for pos in range(len(rb) + 1):
                        nxtb = depot if pos == len(rb) else rb[pos]
                        ins = dist(prevb, c) + dist(c, nxtb) - dist(prevb, nxtb)
                        if ins < best_ins:
                            best_ins = ins
                            best_pos = pos
                        if pos < len(rb):
                            prevb = rb[pos]
                    if rem_gain > best_ins + 1e-12:
                        ra.pop(p)
                        rb.insert(best_pos, c)
                        changed = True
                        break
                if changed:
                    break

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1

    missing = [c for c in customers if seen.get(c, 0) == 0]
    if missing:
        routes = [r for r in routes if r]
        for c in missing:
            best = None
            for ri, r in enumerate(routes):
                load = sum(demand_of(x) for x in r)
                if load + demand_of(c) > capacity:
                    continue
                prev = depot
                for pos in range(len(r) + 1):
                    nxt = depot if pos == len(r) else r[pos]
                    inc = dist(prev, c) + dist(c, nxt) - dist(prev, nxt)
                    key = (inc, ri, pos)
                    if best is None or key < best[0]:
                        best = (key, ri, pos)
                    if pos < len(r):
                        prev = r[pos]
            if best is None:
                routes.append([c])
            else:
                _, ri, pos = best
                routes[ri].insert(pos, c)

    routes = [r for r in routes if r]
    return routes
